{"google_scholar": {"bibtex": "@article{bhattacharya2015investigation,
 title={Investigation and management of the hepatic glycogen storage diseases},
 author={Bhattacharya, Kaustuv},
 journal={Translational pediatrics},
 volume={4},
 number={3},
 pages={240},
 year={2015}
 abstract = {This is quite typical of GSD 1 but can also be seen in GSD III , VI and IX. Sometimes patients present in Profile of an individual patient with GSD III at end of a fasting study taking 2 g/kg of},
}", "parsed": {"doi": null, "year": 2015, "gs_id": null, "pm_id": null, "title": "Investigation and management of the hepatic glycogen storage diseases", "authors": ["Bhattacharya, Kaustuv"], "journal": "Translational pediatrics", "abstract": "This is quite typical of GSD 1 but can also be seen in GSD III , VI and IX. Sometimes patients present in Profile of an individual patient with GSD III at end of a fasting study taking 2 g/kg of", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4729058/", "full_abstract": "Abstract The glycogen storage diseases (GSD) comprise a group of disorders that involve the disruption of metabolism of glycogen. Glycogen is stored in various organs including skeletal muscle, the kidneys and liver. The liver stores glycogen to supply the rest of the body with glucose when required. Therefore, disruption of this process can lead to hypoglycaemia. If glycogen is not broken down effectively, this can lead to hepatomegaly. Glycogen synthase deficiency leads to impaired glycogen synthesis and consequently the liver is small. Glycogen brancher deficiency can lead to abnormal glycogen being stored in the liver leading to a quite different disorder of progressive liver dysfunction. Understanding the physiology of GSD I, III, VI and IX guides dietary treatments and the provision of appropriate amounts and types of carbohydrates. There has been recent re-emergence in the literature of the use of ketones in therapy, either in the form of the salt D,L-3-hydroxybutyrate or medium chain triglyceride (MCT). High protein diets have also been advocated. Alternative waxy maize based starches seem to show promising early data of efficacy. There are many complications of each of these disorders and they need to be prospectively surveyed and managed. Liver and kidney transplantation is still indicated in severe refractory disease. Keywords: Glycogen storage disease (GSD), hypoglycaemia, hepatomegaly, next generation sequencing, waxy maize starch, Glycosade, lactate, ketones, medium chain triglyceride (MCT)", "abstract_snippet": "This is quite typical of GSD 1 but can also be seen in GSD III , VI and IX. Sometimes patients present in Profile of an individual patient with GSD III at end of a fasting study taking 2 g/kg of", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "bibtex", "abstract_supplemented_by_title_query": true}}

