}", "parsed": {"doi": null, "year": 2017, "gs_id": null, "pm_id": null, "title": "Metabolic liver disease in the infant and older child", "authors": ["Chakrapani, Anupam", "Gissen, Paul"], "journal": "Diseases of the liver and biliary system in children", "abstract": "Glycogen storage disease type III GSD type III is caused by deficiency of the debrancher Type IIIa is more common, occurring in about 80\% of patients with GSD III . The inheritance", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://onlinelibrary.wiley.com/doi/abs/10.1002/9781119046936.ch19", "full_abstract": "Summary Inherited metabolic disorders are important causes of liver disease in infancy and childhood. Children with metabolic liver disease may present with hydrops fetalis, liver failure, cirrhosis, cholestasis, or hepato(spleno)megaly. Important groups of inherited metabolic disorders with liver disease include the glycogen storage disorders, hereditary fructose intolerance (HFI), mitochondrial respiratory chain disorders, Alpers syndrome, lysosomal storage disorders, peroxisomal disorders, porphyrias and abetalipoprotinemia. Many of these disorders are treatable; urgent diagnosis and treatment are essential to ensure a good outcome. Specific therapeutic modalities may include dietary treatment, medications, and liver transplantation. Even for inherited metabolic disorders that do not have a specific treatment available, establishing a diagnosis is important for prognosis and genetic counseling. If an inherited metabolic disorder is suspected, discussion with a specialist laboratory is essential in order to plan appropriate investigations in a timely manner. Recent advances in genetic diagnostic techniques (such as next generation sequencing) have enabled a genetic diagnosis to be established in a majority of metabolic disorders. Inherited metabolic disorders are the subject of research into the development of many "newer" therapeutic modalities such as cell therapy and gene therapy, and this should enable effective treatment to be developed for more of these disorders in the near future.", "abstract_snippet": "Glycogen storage disease type III GSD type III is caused by deficiency of the debrancher Type IIIa is more common, occurring in about 80% of patients with GSD III . The inheritance", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "bibtex", "abstract_supplemented_by_title_query": true}}

