}", "parsed": {"doi": null, "year": 2019, "gs_id": null, "pm_id": null, "title": "Hepatic glycogen storage diseases: pathogenesis, clinical symptoms and therapeutic management", "authors": ["Szyma{\'n}ska, Edyta", "J{\'o}{\'z}wiak-Dzi{\k{e}}cielewska, Dominika A", "Gronek, Joanna", "Niewczas, Marta", "Czarny, Wojciech", "Rokicki, Dariusz", "Gronek, Piotr"], "journal": "Archives of medical science: AMS", "abstract": "Hypoglycemia is usually less severe in patients with GSD III /VI/IX due to the intact process of gluconeogenesis [28]. Blood lactate levels increase rapidly in GSD I as blood glucose (BG)", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7959092/", "full_abstract": "Abstract Glycogen storage diseases (GSDs) are genetically determined metabolic diseases that cause disorders of glycogen metabolism in the body. Due to the enzymatic defect at some stage of glycogenolysis/glycogenesis, excess glycogen or its pathologic forms are stored in the body tissues. The first symptoms of the disease usually appear during the first months of life and are thus the domain of pediatricians. Due to the fairly wide access of the authors to unpublished materials and research, as well as direct contact with the GSD patients, the article addresses the problem of actual diagnostic procedures for patients with the suspected diseases. Knowledge and awareness of the problem among physicians seem insufficient, and research on the diagnosis and treatment of GSD is still ongoing, resulting in a heterogeneous GSD typology and a changing way of its diagnosis and treatment. Keywords: glycogen storage disease, hypoglycemia, hepatomegaly", "abstract_snippet": "Hypoglycemia is usually less severe in patients with GSD III /VI/IX due to the intact process of gluconeogenesis [28]. Blood lactate levels increase rapidly in GSD I as blood glucose (BG)", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "bibtex", "abstract_supplemented_by_title_query": true}}

